Maravilhoso! Vamos para a construção do Frontend (React) do Cadastro de Usuários.

Para manter o nosso código organizado e modular, faremos o seguinte:
1. Criar um componente isolado chamado **`UserManagement.tsx`** na pasta **`frontend/src/`** que lidará com a listagem, criação, edição e exclusão de usuários.
2. Atualizar o **`Dashboard.tsx`** na pasta **`frontend/src/`** para renderizar esse novo componente quando a aba ativa for `'usuarios'`.

---

### Passo 1: Criar o Componente `UserManagement.tsx`

Este componente fará requisições para as rotas do Django `/api/usuarios/` (enviando o token) e gerenciará o estado do formulário.

#### O que fazer:

Crie o arquivo **`UserManagement.tsx`** na pasta **`frontend/src/`** com o seguinte código:

```tsx
import { useState, useEffect } from 'react';
import { UserPlus, Edit2, Trash2, Shield, Check, X, AlertCircle } from 'lucide-react';

interface User {
  id: number;
  username: string;
  email: string;
  first_name?: string;
  last_name?: string;
  is_active: boolean;
  groups: number[];
  grupos_nomes: string[];
}

// Simulação de grupos para o formulário (no futuro podem vir de uma API /api/groups/)
const GRUPOS_DISPONIVEIS = [
  { id: 1, nome: 'Administrador' },
  { id: 2, nome: 'Assistente Social' }
];

export default function UserManagement() {
  const [usuarios, setUsuarios] = useState<User[]>([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState<string | null>(null);

  // Estados do Formulário/Modal
  const [modalAberto, setModalAberto] = useState(false);
  const [editandoId, setEditandoId] = useState<number | null>(null);

  const [username, setUsername] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isActive, setIsActive] = useState(true);
  const [selectedGroups, setSelectedGroups] = useState<number[]>([]);

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8001';
  const token = localStorage.getItem('token');

  // Buscar usuários no backend
  const carregarUsuarios = () => {
    setCarregando(true);
    fetch(`${API_URL}/api/usuarios/`, {
      headers: { 'Authorization': `Token ${token}` }
    })
      .then(res => {
        if (!res.ok) throw new Error('Não foi possível carregar os usuários.');
        return res.json();
      })
      .then((data: User[]) => setUsuarios(data))
      .catch(err => setErro(err.message))
      .finally(() => setCarregando(false));
  };

  useEffect(() => {
    carregarUsuarios();
  }, []);

  // Abrir modal para criar novo
  const abrirNovoModal = () => {
    setEditandoId(null);
    setUsername('');
    setFirstName('');
    setLastName('');
    setEmail('');
    setPassword('');
    setIsActive(true);
    setSelectedGroups([]);
    setModalAberto(true);
  };

  // Abrir modal para editar existente
  const abrirEditarModal = (user: User) => {
    setEditandoId(user.id);
    setUsername(user.username);
    setFirstName(user.first_name || '');
    setLastName(user.last_name || '');
    setEmail(user.email);
    setPassword(''); // Deixa a senha em branco na edição (só altera se digitar)
    setIsActive(user.is_active);
    setSelectedGroups(user.groups);
    setModalAberto(true);
  };

  // Salvar (Criar ou Editar)
  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setErro(null);

    const payload: any = {
      username,
      first_name: firstName,
      last_name: lastName,
      email,
      is_active: isActive,
      groups: selectedGroups
    };

    // Só envia senha se for cadastro novo ou se foi preenchida na edição
    if (!editandoId || password) {
      payload.password = password;
    }

    const url = editandoId ? `${API_URL}/api/usuarios/${editandoId}/` : `${API_URL}/api/usuarios/`;
    const method = editandoId ? 'PUT' : 'POST';

    try {
      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Token ${token}`
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.username || data.error || 'Erro ao salvar usuário.');
      }

      setModalAberto(false);
      carregarUsuarios(); // Recarrega a tabela
    } catch (err: any) {
      setErro(err.message);
    }
  };

  // Excluir Usuário
  const handleDelete = async (id: number) => {
    if (!confirm('Tem certeza que deseja excluir este usuário?')) return;

    try {
      const response = await fetch(`${API_URL}/api/usuarios/${id}/`, {
        method: 'DELETE',
        headers: { 'Authorization': `Token ${token}` }
      });

      if (!response.ok) throw new Error('Erro ao excluir usuário.');
      carregarUsuarios();
    } catch (err: any) {
      setErro(err.message);
    }
  };

  const handleGroupToggle = (groupId: number) => {
    setSelectedGroups(prev => 
      prev.includes(groupId) ? prev.filter(id => id !== groupId) : [...prev, groupId]
    );
  };

  return (
    <div className="user-management">
      <div className="welcome-section" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div>
          <h1 className="welcome-title">Gestão de Usuários</h1>
          <p className="welcome-subtitle">Gerencie os operadores do sistema e seus níveis de acesso.</p>
        </div>
        <button onClick={abrirNovoModal} className="btn-logout" style={{ color: '#ffffff', backgroundColor: '#f5911e', borderColor: '#f5911e', display: 'flex', gap: '8px', alignItems: 'center' }}>
          <UserPlus size={18} />
          <span>Novo Usuário</span>
        </button>
      </div>

      {erro && (
        <div style={{ backgroundColor: '#fee2e2', border: '1px solid #fca5a5', color: '#b91c1c', padding: '12px', borderRadius: '8px', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <AlertCircle size={18} />
          <span>{erro}</span>
        </div>
      )}

      <div className="dashboard-card">
        <div className="card-body" style={{ padding: 0 }}>
          {carregando ? (
            <div style={{ padding: '40px', textAlign: 'center', color: '#64748b' }}>Carregando operadores...</div>
          ) : (
            <table className="dashboard-table">
              <thead>
                <tr>
                  <th>Nome Completo</th>
                  <th>Usuário</th>
                  <th>E-mail</th>
                  <th>Perfil de Acesso</th>
                  <th>Status</th>
                  <th style={{ textAlign: 'right' }}>Ações</th>
                </tr>
              </thead>
              <tbody>
                {usuarios.map(user => (
                  <tr key={user.id}>
                    <td>
                      <span className="font-semibold">{user.first_name} {user.last_name}</span>
                    </td>
                    <td>{user.username}</td>
                    <td>{user.email}</td>
                    <td>
                      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                        {user.grupos_nomes.length === 0 ? (
                          <span style={{ fontSize: '11px', color: '#94a3b8' }}>Sem grupo</span>
                        ) : (
                          user.grupos_nomes.map((nome, idx) => (
                            <span key={idx} style={{ display: 'flex', alignItems: 'center', gap: '4px', padding: '2px 8px', backgroundColor: '#eff6ff', color: '#1e40af', borderRadius: '4px', fontSize: '11px', fontWeight: 600 }}>
                              <Shield size={10} />
                              {nome}
                            </span>
                          ))
                        )}
                      </div>
                    </td>
                    <td>
                      <span className={`status-badge ${user.is_active ? 'status-done' : 'status-pending'}`}>
                        {user.is_active ? 'Ativo' : 'Inativo'}
                      </span>
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
                        <button onClick={() => abrirEditarModal(user)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
                          <Edit2 size={16} />
                        </button>
                        <button onClick={() => handleDelete(user.id)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ef4444' }}>
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* MODAL DE FORMULÁRIO */}
      {modalAberto && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div className="bg-form" style={{ width: '100%', maxWidth: '500px', padding: '24px', backgroundColor: '#ffffff' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 700, color: '#0f172a' }}>
                {editandoId ? 'Editar Operador' : 'Novo Operador'}
              </h3>
              <button onClick={() => setModalAberto(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Nome</label>
                  <input type="text" className="form-control" value={firstName} onChange={e => setFirstName(e.target.value)} required />
                </div>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Sobrenome</label>
                  <input type="text" className="form-control" value={lastName} onChange={e => setLastName(e.target.value)} />
                </div>
              </div>

              <div>
                <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>E-mail</label>
                <input type="email" className="form-control" value={email} onChange={e => setEmail(e.target.value)} required />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Usuário (Login)</label>
                  <input type="text" className="form-control" value={username} onChange={e => setUsername(e.target.value)} required disabled={!!editandoId} />
                </div>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Senha {editandoId && '(opcional)'}</label>
                  <input type="password" className="form-control" value={password} onChange={e => setPassword(e.target.value)} required={!editandoId} placeholder={editandoId ? 'Deixe em branco p/ manter' : ''} />
                </div>
              </div>

              <div>
                <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '6px' }}>Perfis de Acesso</label>
                <div style={{ display: 'flex', gap: '12px' }}>
                  {GRUPOS_DISPONIVEIS.map(g => (
                    <label key={g.id} style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13px' }}>
                      <input type="checkbox" checked={selectedGroups.includes(g.id)} onChange={() => handleGroupToggle(g.id)} />
                      {g.nome}
                    </label>
                  ))}
                </div>
              </div>

              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input type="checkbox" id="isActiveCheck" checked={isActive} onChange={e => setIsActive(e.target.checked)} />
                <label htmlFor="isActiveCheck" style={{ fontSize: '13px', cursor: 'pointer' }}>Usuário Ativo</label>
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={() => setModalAberto(false)} className="form-control" style={{ maxWidth: '100px', cursor: 'pointer' }}>Cancelar</button>
                <button type="submit" className="btn conecta text-white" style={{ maxWidth: '120px', marginTop: 0 }}>Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
