                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Unidade Socioassistencial? *</label>
                      <select className="form-control" value={unidadeSocioassistencial ? 'true' : 'false'} onChange={e => setUnidadeSocioassistencial(e.target.value === 'true')}>
                        <option value="false">Não</option>
                        <option value="true">Sim</option>
                      </select>
                    </div>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Responsável pelo Órgão? *</label>
                      <select className="form-control" value={responsavelOrgao ? 'true' : 'false'} onChange={e => setResponsavelOrgao(e.target.value === 'true')}>
                        <option value="false">Não</option>
                        <option value="true">Sim</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Órgão / Unidade *</label>
                    <input type="text" id="input-orgao" className="form-control" value={orgao} onChange={e => setOrgao(e.target.value)} />
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Tipo Servidor *</label>
                      <input type="text" id="input-tiposervidor" className="form-control" value={tipoServidor} onChange={e => setTipoServidor(e.target.value)} />
                    </div>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Profissão *</label>
                      <input type="text" id="input-profissao" className="form-control" value={profissao} onChange={e => setProfissao(e.target.value)} />
                    </div>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Função *</label>
                      <input type="text" id="input-funcao" className="form-control" value={funcao} onChange={e => setFuncao(e.target.value)} />
                    </div>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Nº Conselho de Classe *</label>
                      <input type="text" id="input-numconselhoclasse" className="form-control" value={numConselhoClasse} onChange={e => setNumConselhoClasse(e.target.value)} />
                    </div>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Início do Trabalho</label>
                      <input type="date" className="form-control" value={dataInicioTrabalho} onChange={e => setDataInicioTrabalho(e.target.value)} />
                    </div>
                    <div>
                      <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Fim do Trabalho</label>
                      <input type="date" className="form-control" value={dataFimTrabalho} onChange={e => setDataFimTrabalho(e.target.value)} />
                    </div>
                  </div>
                </div>
              )}

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '16px', borderTop: '1px solid #e2e8f0', paddingTop: '16px' }}>
                <button type="button" onClick={() => setModalAberto(false)} className="form-control" style={{ maxWidth: '100px', cursor: 'pointer' }}>Cancelar</button>
                <button type="submit" className="btn conecta text-white" style={{ maxWidth: '120px', marginTop: 0 }}>Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE ERRO INDEPENDENTE (ALERT DIALOG) */}
      {errorModalMsg && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.75)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
          <div style={{ width: '100%', maxWidth: '400px', padding: '24px', backgroundColor: '#ffffff', borderRadius: '12px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)', display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', gap: '16px' }}>
            <div style={{ padding: '12px', backgroundColor: '#fee2e2', borderRadius: '9999px', color: '#ef4444' }}>
              <AlertCircle size={32} />
            </div>
            <div>
              <h4 style={{ margin: '0 0 8px 0', fontSize: '1.1rem', fontWeight: 700, color: '#0f172a' }}>Validação Falhou</h4>
              <p style={{ margin: 0, fontSize: '0.9rem', color: '#475569', lineHeight: 1.5 }}>{errorModalMsg}</p>
            </div>
            <button type="button" onClick={fecharErrorModal} className="btn conecta text-white" style={{ width: '100%', marginTop: '8px' }}>
              Fechar e Corrigir
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

from rest_framework import serializers
from django.contrib.auth.models import Group
from core.models import Menu

class SubmenuSerializer(serializers.ModelSerializer):
    class Meta:
        model = Menu
        fields = ['id', 'nome', 'url', 'icone', 'ordem']

class MenuSerializer(serializers.ModelSerializer):
    submenus = serializers.SerializerMethodField()

    class Meta:
        model = Menu
        fields = ['id', 'nome', 'url', 'icone', 'ordem', 'submenus']

    def get_submenus(self, obj):
        # Filtra apenas submenus ativos e ordenados para exibição do menu lateral
        ativos = obj.submenus.filter(ativo=True).order_by('ordem', 'nome')
        return SubmenuSerializer(ativos, many=True).data

class GroupSerializer(serializers.ModelSerializer):
    class Meta:
        model = Group
        fields = ['id', 'name']

class MenuGerenciamentoSerializer(serializers.ModelSerializer):
    grupos_nomes = serializers.SerializerMethodField(read_only=True)
    pai_nome = serializers.SerializerMethodField(read_only=True)

    class Meta:
        model = Menu
        fields = ['id', 'nome', 'url', 'icone', 'pai', 'pai_nome', 'ordem', 'ativo', 'grupos', 'grupos_nomes']

    def get_grupos_nomes(self, obj):
        return [g.name for g in obj.grupos.all()]

    def get_pai_nome(self, obj):
        return obj.pai.nome if obj.pai else None

import { useState, useEffect } from 'react';
import { Menu as MenuIcon, Plus, Edit2, Trash2, X, AlertCircle } from 'lucide-react';

interface Menu {
  id: number;
  nome: string;
  url?: string;
  icone?: string;
  pai?: number;
  pai_nome?: string;
  ordem: number;
  ativo: boolean;
  grupos: number[];
  grupos_nomes: string[];
}

interface Grupo {
  id: number;
  name: string;
}

export default function MenuManagement() {
  const [menus, setMenus] = useState<Menu[]>([]);
  const [grupos, setGrupos] = useState<Grupo[]>([]);
  const [carregando, setCarregando] = useState(true);

  // Modais de Erro
  const [errorModalMsg, setErrorModalMsg] = useState<string | null>(null);
  const [fieldToFocus, setFieldToFocus] = useState<{ id: string } | null>(null);

  // Estados do Formulário/Modal
  const [modalAberto, setModalAberto] = useState(false);
  const [editandoId, setEditandoId] = useState<number | null>(null);

  // Campos do Formulário
  const [nome, setNome] = useState('');
  const [url, setUrl] = useState('');
  const [icone, setIcone] = useState('');
  const [pai, setPai] = useState<number | undefined>(undefined);
  const [ordem, setOrdem] = useState(0);
  const [ativo, setAtivo] = useState(true);
  const [selectedGroups, setSelectedGroups] = useState<number[]>([]);

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8001';
  const token = localStorage.getItem('token');

  // Carregar Menus e Grupos de Acesso
  const carregarDados = async () => {
    setCarregando(true);
    try {
      const headers = { 'Authorization': `Token ${token}` };

      // Buscar Menus
      const resMenus = await fetch(`${API_URL}/api/gerenciamento-menus/`, { headers });
      if (!resMenus.ok) throw new Error('Não foi possível carregar os menus.');
      const dataMenus = await resMenus.json();
      setMenus(dataMenus);

      // Buscar Grupos/Perfis
      const resGrupos = await fetch(`${API_URL}/api/grupos/`, { headers });
      if (!resGrupos.ok) throw new Error('Não foi possível carregar os perfis de acesso.');
      const dataGrupos = await resGrupos.json();
      setGrupos(dataGrupos);

    } catch (err: any) {
      setErrorModalMsg(err.message);
    } finally {
      setCarregando(false);
    }
  };

  useEffect(() => {
    carregarDados();
  }, []);

  const fecharErrorModal = () => {
    setErrorModalMsg(null);
    if (fieldToFocus) {
      setTimeout(() => {
        const el = document.getElementById(fieldToFocus.id);
        if (el) el.focus();
        setFieldToFocus(null);
      }, 100);
    }
  };

  const abrirNovoModal = () => {
    setEditandoId(null);
    setNome('');
    setUrl('');
    setIcone('');
    setPai(undefined);
    setOrdem(0);
    setAtivo(true);
    setSelectedGroups([]);
    setFieldToFocus(null);
    setModalAberto(true);
  };

  const abrirEditarModal = (menu: Menu) => {
    setEditandoId(menu.id);
    setNome(menu.nome);
    setUrl(menu.url || '');
    setIcone(menu.icone || '');
    setPai(menu.pai || undefined);
    setOrdem(menu.ordem);
    setAtivo(menu.ativo);
    setSelectedGroups(menu.grupos);
    setFieldToFocus(null);
    setModalAberto(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!nome.trim()) {
      setFieldToFocus({ id: 'input-nome' });
      setErrorModalMsg('O campo Nome do Menu é obrigatório.');
      return;
    }

    const payload = {
      nome,
      url: url.trim() || null,
      icone: icone.trim() || null,
      pai: pai || null,
      ordem: Number(ordem),
      ativo,
      grupos: selectedGroups
    };

    const targetUrl = editandoId ? `${API_URL}/api/gerenciamento-menus/${editandoId}/` : `${API_URL}/api/gerenciamento-menus/`;
    const method = editandoId ? 'PUT' : 'POST';

    try {
      const response = await fetch(targetUrl, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Token ${token}`
        },
        body: JSON.stringify(payload)
      });

      const data = await response.json();

      if (!response.ok) {
        if (data.nome) {
          setFieldToFocus({ id: 'input-nome' });
          throw new Error('O nome do menu é obrigatório ou possui erro.');
        }
        throw new Error(data.error || data.detail || 'Erro ao salvar o menu.');
      }

      setModalAberto(false);
      carregarDados();
    } catch (err: any) {
      setErrorModalMsg(err.message);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm('Deseja realmente excluir este menu? Todos os submenus vinculados também podem ser afetados.')) return;

    try {
      const response = await fetch(`${API_URL}/api/gerenciamento-menus/${id}/`, {
        method: 'DELETE',
        headers: { 'Authorization': `Token ${token}` }
      });

      if (!response.ok) throw new Error('Erro ao excluir o menu.');
      carregarDados();
    } catch (err: any) {
      setErrorModalMsg(err.message);
    }
  };

  const handleGroupToggle = (groupId: number) => {
    setSelectedGroups(prev =>
      prev.includes(groupId) ? prev.filter(id => id !== groupId) : [...prev, groupId]
    );
  };

  // Filtra apenas os menus que não possuem pai para servir de opção para "Menu Pai" (evita aninhamento infinito)
  const menusPrincipaisPossiveis = menus.filter(m => !m.pai && m.id !== editandoId);

  return (
    <div className="menu-management">
      <div className="welcome-section" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div>
          <h1 className="welcome-title">Gerenciamento de Menus</h1>
          <p className="welcome-subtitle">Configure o menu lateral dinâmico do sistema e as permissões dos perfis de acesso.</p>
        </div>
        <button onClick={abrirNovoModal} className="btn-logout" style={{ color: '#ffffff', backgroundColor: '#f5911e', borderColor: '#f5911e', display: 'flex', gap: '8px', alignItems: 'center', width: 'auto' }}>
          <Plus size={18} />
          <span>Novo Menu</span>
        </button>
      </div>

      <div className="dashboard-card">
        <div className="card-body" style={{ padding: 0 }}>
          {carregando ? (
            <div style={{ padding: '40px', textAlign: 'center', color: '#64748b' }}>Carregando estrutura de menus...</div>
          ) : (
            <table className="dashboard-table">
              <thead>
                <tr>
                  <th>Nome do Menu</th>
                  <th>Menu Pai</th>
                  <th>Caminho (URL)</th>
                  <th>Ícone (Lucide)</th>
                  <th>Ordem</th>
                  <th>Status</th>
                  <th>Perfis com Acesso</th>
                  <th style={{ textAlign: 'right' }}>Ações</th>
                </tr>
              </thead>
              <tbody>
                {menus.map(menu => (
                  <tr key={menu.id}>
                    <td>
                      <span className="font-semibold" style={{ paddingLeft: menu.pai ? '16px' : '0', color: menu.pai ? '#475569' : '#0f172a' }}>
                        {menu.pai ? '↳ ' : ''}{menu.nome}
                      </span>
                    </td>
                    <td>
                      {menu.pai_nome ? (
                        <span style={{ fontSize: '12px', color: '#64748b', fontWeight: 600 }}>{menu.pai_nome}</span>
                      ) : (
                        <span style={{ fontSize: '11px', color: '#94a3b8', fontStyle: 'italic' }}>Menu Principal</span>
                      )}
                    </td>
                    <td>{menu.url || <span style={{ color: '#94a3b8' }}>-</span>}</td>
                    <td>
                      <span style={{ fontFamily: 'monospace', fontSize: '12px', color: '#64748b' }}>{menu.icone || '-'}</span>
                    </td>
                    <td>{menu.ordem}</td>
                    <td>
                      <span className={`status-badge ${menu.ativo ? 'status-done' : 'status-pending'}`}>
                        {menu.ativo ? 'Ativo' : 'Inativo'}
                      </span>
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                        {menu.grupos_nomes.length === 0 ? (
                          <span style={{ fontSize: '11px', color: '#94a3b8', fontStyle: 'italic' }}>Todos os perfis</span>
                        ) : (
                          menu.grupos_nomes.map((nome, idx) => (
                            <span key={idx} style={{ padding: '2px 8px', backgroundColor: '#eff6ff', color: '#1e40af', borderRadius: '4px', fontSize: '11px', fontWeight: 600 }}>
                              {nome}
                            </span>
                          ))
                        )}
                      </div>
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
                        <button onClick={() => abrirEditarModal(menu)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
                          <Edit2 size={16} />
                        </button>
                        <button onClick={() => handleDelete(menu.id)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ef4444' }}>
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* MODAL DE CADASTRO / EDIÇÃO */}
      {modalAberto && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div className="bg-form" style={{ width: '100%', maxWidth: '500px', padding: '24px', backgroundColor: '#ffffff', borderRadius: '12px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 700, color: '#0f172a' }}>
                {editandoId ? 'Editar Item de Menu' : 'Novo Item de Menu'}
              </h3>
              <button type="button" onClick={() => setModalAberto(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div>
                <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Nome do Menu *</label>
                <input type="text" id="input-nome" className="form-control" value={nome} onChange={e => setNome(e.target.value)} placeholder="Ex: Cadastros, Usuários" />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Caminho (URL)</label>
                  <input type="text" className="form-control" value={url} onChange={e => setUrl(e.target.value)} placeholder="Ex: usuarios, Relatorios" />
                </div>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Ícone (Lucide)</label>
                  <input type="text" className="form-control" value={icone} onChange={e => setIcone(e.target.value)} placeholder="Ex: Users, Settings, Folder" />
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Menu Pai (Opcional)</label>
                  <select className="form-control" value={pai || ''} onChange={e => setPai(e.target.value ? Number(e.target.value) : undefined)}>
                    <option value="">Nenhum (Menu Principal)</option>
                    {menusPrincipaisPossiveis.map(m => (
                      <option key={m.id} value={m.id}>{m.nome}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '4px' }}>Ordem de Exibição</label>
                  <input type="number" className="form-control" value={ordem} onChange={e => setOrdem(Number(e.target.value))} />
                </div>
              </div>

              <div>
                <label style={{ fontSize: '12px', fontWeight: 600, color: '#475569', display: 'block', marginBottom: '6px' }}>Perfis com Permissão de Acesso</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  {grupos.map(g => (
                    <label key={g.id} style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13px' }}>
                      <input type="checkbox" checked={selectedGroups.includes(g.id)} onChange={() => handleGroupToggle(g.id)} />
                      {g.name}
                    </label>
                  ))}
                  {grupos.length === 0 && (
                    <span style={{ fontSize: '12px', color: '#94a3b8', fontStyle: 'italic' }}>Carregando perfis...</span>
                  )}
                </div>
                <small style={{ color: '#64748b', fontSize: '11px', display: 'block', marginTop: '4px' }}>Se nenhum perfil for selecionado, todos os usuários logados terão acesso.</small>
              </div>

              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <input type="checkbox" id="isAtivoCheck" checked={ativo} onChange={e => setAtivo(e.target.checked)} />
                <label htmlFor="isAtivoCheck" style={{ fontSize: '13px', cursor: 'pointer' }}>Menu Ativo</label>
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={() => setModalAberto(false)} className="form-control" style={{ maxWidth: '100px', cursor: 'pointer' }}>Cancelar</button>
                <button type="submit" className="btn conecta text-white" style={{ maxWidth: '120px', marginTop: 0 }}>Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE ERRO */}
      {errorModalMsg && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.75)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
          <div style={{ width: '100%', maxWidth: '400px', padding: '24px', backgroundColor: '#ffffff', borderRadius: '12px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)', display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', gap: '16px' }}>
            <div style={{ padding: '12px', backgroundColor: '#fee2e2', borderRadius: '9999px', color: '#ef4444' }}>
              <AlertCircle size={32} />
            </div>
            <div>
              <h4 style={{ margin: '0 0 8px 0', fontSize: '1.1rem', fontWeight: 700, color: '#0f172a' }}>Erro de Validação</h4>
              <p style={{ margin: 0, fontSize: '0.9rem', color: '#475569', lineHeight: 1.5 }}>{errorModalMsg}</p>
            </div>
            <button type="button" onClick={fecharErrorModal} className="btn conecta text-white" style={{ width: '100%', marginTop: '8px' }}>
              Fechar e Corrigir
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

