// Estados e função para Auto-completar do CBO
interface CboItem {
  id: number;
  codigo: number;
  nome: string;
}
const [cboSuggestions, setCboSuggestions] = useState<CboItem[]>([]);
const [showCboSuggestions, setShowCboSuggestions] = useState(false);

const buscarCBOs = async (busca: string) => {
  if (busca.trim().length < 2) {
    setCboSuggestions([]);
    return;
  }
  try {
    const res = await fetch(`${API_URL}/api/cbos/?search=${encodeURIComponent(busca)}`, {
      headers: { 'Authorization': `Token ${token}` }
    });
    if (res.ok) {
      const data = await res.json();
      setCboSuggestions(data.results || []);
    }
  } catch (err) {
    console.error(err);
  }
};

// Estados e função para Auto-completar do Tipo de Função
interface FuncaoItem {
  id: number;
  nome: string;
}
const [funcaoSuggestions, setFuncaoSuggestions] = useState<FuncaoItem[]>([]);
const [showFuncaoSuggestions, setShowFuncaoSuggestions] = useState(false);

const buscarTiposFuncao = async (busca: string) => {
  if (busca.trim().length < 2) {
    setFuncaoSuggestions([]);
    return;
  }
  try {
    const res = await fetch(`${API_URL}/api/tipo_funcao/?search=${encodeURIComponent(busca)}`, {
      headers: { 'Authorization': `Token ${token}` }
    });
    if (res.ok) {
      const data = await res.json();
      setFuncaoSuggestions(data.results || []);
    }
  } catch (err) {
    console.error(err);
  }
};

